package com.savora.api; import com.savora.model.*; import com.savora.repo.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/me") public class UserController { final UserRepo users;final AddressRepo addresses;final WishlistRepo wishlist;final FoodRepo foods; public UserController(UserRepo u,AddressRepo a,WishlistRepo w,FoodRepo f){users=u;addresses=a;wishlist=w;foods=f;} User user(Authentication a){return users.findByEmail(a.getName()).orElseThrow();} @GetMapping Api<?> me(Authentication a){var u=user(a);return Api.ok(new UserDto(u.id,u.name,u.email,u.phone,u.role.name(),u.avatar));} @PutMapping Api<?> update(Authentication a,@RequestBody Map<String,String>x){var u=user(a);u.name=x.getOrDefault("name",u.name);u.phone=x.getOrDefault("phone",u.phone);u.avatar=x.getOrDefault("avatar",u.avatar);users.save(u);return Api.ok(u);} @GetMapping("/addresses") Api<?> addresses(Authentication a){return Api.ok(addresses.findByUserId(user(a).id));} @PostMapping("/addresses") Api<?> address(Authentication a,@RequestBody Address x){x.id=null;x.user=user(a);return Api.ok(addresses.save(x));} @DeleteMapping("/addresses/{id}") Api<?> removeAddress(Authentication a,@PathVariable Long id){var x=addresses.findById(id).orElseThrow();if(!x.user.id.equals(user(a).id))throw new SecurityException("Forbidden");addresses.delete(x);return Api.ok(Map.of("deleted",true));} @GetMapping("/wishlist") Api<?> wish(Authentication a){return Api.ok(wishlist.findByUserId(user(a).id).stream().map(w->w.food).toList());} @PostMapping("/wishlist/{id}") Api<?> toggle(Authentication a,@PathVariable Long id){var u=user(a);if(wishlist.existsByUserIdAndFoodId(u.id,id))wishlist.deleteByUserIdAndFoodId(u.id,id);else {var w=new WishlistItem();w.user=u;w.food=foods.findById(id).orElseThrow();wishlist.save(w);}return Api.ok(Map.of("saved",wishlist.existsByUserIdAndFoodId(u.id,id)));} }
